  1	import java.util.ArrayList;
  2	import java.util.Comparator;
  3	import java.util.Objects;
  4	import java.util.PriorityQueue;
  5	import java.util.function.BiConsumer;
  6	
  7	class HuffmanCoding {
  8	
  9	    private static final int INTERNAL_NODE_SYMBOL_INDEX = -1;
 10	    private static final String SINGLE_SYMBOL_CODE = "0";
 11	
 12	    private static final Comparator<Node> NODE_ORDER = Comparator
 13	            .comparingLong((Node node) -> node.frequency)
 14	            .thenComparingInt(node -> node.firstSymbolIndex);
 15	
 16	    private HuffmanCoding() {
 17	    }
 18	
 19	    private static final class Node {
 20	        private final long frequency;
 21	        private final int firstSymbolIndex;
 22	        private final int symbolIndex;
 23	        private final Node left;
 24	        private final Node right;
 25	
 26	        private Node(int frequency, int symbolIndex) {
 27	            this.frequency = frequency;
 28	            this.firstSymbolIndex = symbolIndex;
 29	            this.symbolIndex = symbolIndex;
 30	            this.left = null;
 31	            this.right = null;
 32	        }
 33	
 34	        private Node(Node left, Node right) {
 35	            this.frequency = left.frequency + right.frequency;
 36	            this.firstSymbolIndex = Math.min(left.firstSymbolIndex, right.firstSymbolIndex);
 37	            this.symbolIndex = INTERNAL_NODE_SYMBOL_INDEX;
 38	            this.left = left;
 39	            this.right = right;
 40	        }
 41	
 42	        private boolean isLeaf() {
 43	            return left == null && right == null;
 44	        }
 45	    }
 46	
 47	    private static final class HuffmanTree {
 48	        private final Node root;
 49	        private final int symbolCount;
 50	
 51	        private HuffmanTree(Node root, int symbolCount) {
 52	            this.root = root;
 53	            this.symbolCount = symbolCount;
 54	        }
 55	
 56	        private static HuffmanTree build(String symbols, int[] frequencies) {
 57	            validateInput(symbols, frequencies);
 58	            Node root = symbols.isEmpty() ? null : buildTree(frequencies);
 59	            return new HuffmanTree(root, symbols.length());
 60	        }
 61	
 62	        private ArrayList<String> codesInTraversalOrder() {
 63	            ArrayList<String> codes = new ArrayList<>(symbolCount);
 64	            collectLeafCodes(root, new StringBuilder(), (leaf, code) -> codes.add(code));
 65	            return codes;
 66	        }
 67	
 68	        private ArrayList<String> codesBySymbolOrder() {
 69	            ArrayList<String> codes = createEmptyCodeList(symbolCount);
 70	            collectLeafCodes(root, new StringBuilder(), (leaf, code) -> codes.set(leaf.symbolIndex, code));
 71	            return codes;
 72	        }
 73	
 74	        private static Node buildTree(int[] frequencies) {
 75	            PriorityQueue<Node> nodes = createLeafQueue(frequencies);
 76	
 77	            while (nodes.size() > 1) {
 78	                nodes.add(mergeLowestFrequencyNodes(nodes));
 79	            }
 80	
 81	            return nodes.poll();
 82	        }
 83	
 84	        private static PriorityQueue<Node> createLeafQueue(int[] frequencies) {
 85	            PriorityQueue<Node> nodes = new PriorityQueue<>(NODE_ORDER);
 86	
 87	            for (int i = 0; i < frequencies.length; i++) {
 88	                nodes.add(new Node(frequencies[i], i));
 89	            }
 90	
 91	            return nodes;
 92	        }
 93	
 94	        private static Node mergeLowestFrequencyNodes(PriorityQueue<Node> nodes) {
 95	            Node left = nodes.poll();
 96	            Node right = nodes.poll();
 97	            return new Node(left, right);
 98	        }
 99	
100	        private static ArrayList<String> createEmptyCodeList(int size) {
101	            ArrayList<String> codes = new ArrayList<>(size);
102	
103	            for (int i = 0; i < size; i++) {
104	                codes.add("");
105	            }
106	
107	            return codes;
108	        }
109	
110	        private static void collectLeafCodes(Node root, StringBuilder prefix, BiConsumer<Node, String> consumer) {
111	            if (root == null) {
112	                return;
113	            }
114	
115	            if (root.isLeaf()) {
116	                consumer.accept(root, codeFor(prefix));
117	                return;
118	            }
119	
120	            appendBranchCode(root.left, '0', prefix, consumer);
121	            appendBranchCode(root.right, '1', prefix, consumer);
122	        }
123	
124	        private static void appendBranchCode(Node node, char bit, StringBuilder prefix, BiConsumer<Node, String> consumer) {
125	            prefix.append(bit);
126	            collectLeafCodes(node, prefix, consumer);
127	            prefix.setLength(prefix.length() - 1);
128	        }
129	
130	        private static String codeFor(StringBuilder prefix) {
131	            return prefix.length() == 0 ? SINGLE_SYMBOL_CODE : prefix.toString();
132	        }
133	    }
134	
135	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
136	        return HuffmanTree.build(symbols, frequencies).codesInTraversalOrder();
137	    }
138	
139	    static ArrayList<String> huffmanCodesBySymbol(String symbols, int[] frequencies) {
140	        return HuffmanTree.build(symbols, frequencies).codesBySymbolOrder();
141	    }
142	
143	    private static void validateInput(String symbols, int[] frequencies) {
144	        Objects.requireNonNull(symbols, "Input string must not be null");
145	        Objects.requireNonNull(frequencies, "Frequency array must not be null");
146	
147	        if (symbols.length() != frequencies.length) {
148	            throw new IllegalArgumentException("Input string and frequency array must have the same length");
149	        }
150	    }
151	
152	    public static void main(String[] args) {
153	        String s = "abcdef";
154	        int[] freq = {5, 9, 12, 13, 16, 45};
155	        ArrayList<String> codes = huffmanCodes(s, freq);
156	
157	        for (String code : codes) {
158	            System.out.print(code + " ");
159	        }
160	    }
161	}

